batch_01.query:
SELECT DISTINCT ?word ?item ?itemDesc ?rel ?type ?typeLabel ?typeDesc ?enwiki WHERE {
  VALUES ?word { "angle"@en "arc"@en "artery"@en "axis"@en "axle"@en "bark"@en "bearing"@en "belt"@en "blizzard"@en "blossom"@en "bone"@en "brain"@en "branch"@en "breeze"@en "bud"@en "cam"@en "cartilage"@en "ceremony"@en "charter"@en "chill"@en "chord"@en "circle"@en "circuit"@en "climate"@en }
  ?item rdfs:label ?word .
  { ?item wdt:P31 ?type . BIND("instance of" AS ?rel) }
  UNION
  { ?item wdt:P279 ?type . BIND("subclass of" AS ?rel) }
  OPTIONAL { ?item schema:description ?itemDesc . FILTER(LANG(?itemDesc) = "en") }
  OPTIONAL { ?type schema:description ?typeDesc . FILTER(LANG(?typeDesc) = "en") }
  OPTIONAL { ?article schema:about ?item ;
                      schema:isPartOf <https://en.wikipedia.org/> ;
                      schema:name ?enwiki . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

